RECORD_ID = "JAH-SWR-000001"
DATA = {
  "Sealed": "Exists; closed to public",
  "Expunged": "Legally destroyed",
  "Redacted": "Partially released"
}

def lookup(key):
    """Return the detail for a given fact."""
    return DATA.get(str(key), "No entry for %%s" %% key)

def all_keys():
    return sorted(DATA.keys())

